/**
 * Per-workflow MCP tool JSON loading (`.trailstep/mcp/trst_<id>.json`).
 *
 * The JSON files are generated by the CLI (see
 * `packages/cli/src/internals/mcp-tools/mcp-tool-generation.ts`) on
 * `trailstep add` / `trailstep update` only; this module performs no
 * generation or regeneration. It reads the layered tool JSONs fresh through
 * `@trailstep/core`'s `load()` (local > project > global, first match wins per
 * file id), validates each payload structurally, and maps each valid payload
 * to an MCP tool definition (`trst_<id>` with `properties`/`required` taken
 * from the JSON `inputSchema` so agents see the workflow's params).
 *
 * Malformed payloads are skipped with a warning; JSON files whose `name` is
 * not a `trst_`-prefixed tool name are not per-workflow tool JSONs and are
 * skipped silently.
 */
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import path from "node:path";

import { load, validateStructural } from "@trailstep/core";

export interface PerWorkflowToolDefinition {
  readonly name: string;
  readonly description: string;
  /** Ref the MCP server presets when dispatching the tool to runWorkflowTool. */
  readonly workflowRef: string;
  readonly inputSchema: {
    readonly type: "object";
    readonly properties: Record<string, unknown>;
    readonly required?: readonly string[];
  };
}

export interface LoadPerWorkflowToolsOptions {
  /** Project directory anchoring the local/project layers. */
  readonly projectDir?: string;
  /** Home directory anchoring the global layer (tests inject a tmp dir). */
  readonly homeDir?: string;
}

/** Config `mcp.perWorkflowTools` default: per-workflow tools are exposed. */
export const DEFAULT_PER_WORKFLOW_TOOLS = true;

/**
 * Loads and validates every layered per-workflow tool JSON. Duplicate tool
 * names keep the first occurrence (layering order).
 */
export function loadPerWorkflowTools(
  options: LoadPerWorkflowToolsOptions = {},
): PerWorkflowToolDefinition[] {
  const items = load({
    ...(options.projectDir === undefined ? {} : { projectDir: options.projectDir }),
    ...(options.homeDir === undefined ? {} : { homeDir: options.homeDir }),
  });

  const byName = new Map<string, PerWorkflowToolDefinition>();
  for (const item of items) {
    const parsed = parsePerWorkflowToolJson(item);
    if (parsed === "not-a-tool") {
      continue;
    }
    if (parsed === undefined) {
      continue;
    }
    if (!byName.has(parsed.name)) {
      byName.set(parsed.name, parsed);
    }
  }
  return [...byName.values()];
}

/**
 * Resolves the `mcp.perWorkflowTools` mode flag from the layered config files
 * (`~/.trailstep/config.json` < `<project>/.trailstep/config.json` <
 * `<project>/.trailstep/config-local.json`, shallow top-level merge matching
 * the CLI's config merge). Defaults to {@link DEFAULT_PER_WORKFLOW_TOOLS} when
 * the section or key is absent; malformed files and invalid values are
 * reported on stderr and fall back to the default so the server stays usable.
 */
export function resolvePerWorkflowToolsEnabled(options: LoadPerWorkflowToolsOptions = {}): boolean {
  const projectDir = options.projectDir ? path.resolve(options.projectDir) : process.cwd();
  const homeDir = options.homeDir ? path.resolve(options.homeDir) : homedir();

  const configPaths: { readonly label: string; readonly filePath: string }[] = [
    {
      label: "~/.trailstep/config.json",
      filePath: path.join(homeDir, ".trailstep", "config.json"),
    },
    {
      label: ".trailstep/config.json",
      filePath: path.join(projectDir, ".trailstep", "config.json"),
    },
    {
      label: ".trailstep/config-local.json",
      filePath: path.join(projectDir, ".trailstep", "config-local.json"),
    },
  ];

  let merged: Record<string, unknown> = {};
  for (const { label, filePath } of configPaths) {
    const raw = readRawJsonRecord(filePath, label);
    if (raw !== undefined) {
      merged = { ...merged, ...raw };
    }
  }

  const mcp = merged.mcp;
  if (mcp === undefined) {
    return DEFAULT_PER_WORKFLOW_TOOLS;
  }
  if (!isRecord(mcp)) {
    console.error(
      `Warning: .trailstep/config.json "mcp" must be an object; using mcp.perWorkflowTools=${DEFAULT_PER_WORKFLOW_TOOLS}.`,
    );
    return DEFAULT_PER_WORKFLOW_TOOLS;
  }
  const value = mcp.perWorkflowTools;
  if (value === undefined) {
    return DEFAULT_PER_WORKFLOW_TOOLS;
  }
  if (typeof value !== "boolean") {
    console.error(
      `Warning: .trailstep/config.json "mcp.perWorkflowTools" must be a boolean; using mcp.perWorkflowTools=${DEFAULT_PER_WORKFLOW_TOOLS}.`,
    );
    return DEFAULT_PER_WORKFLOW_TOOLS;
  }
  return value;
}

type ParsedPerWorkflowTool = PerWorkflowToolDefinition | "not-a-tool";

/**
 * Validates one loaded tool JSON payload.
 *
 * Returns `"not-a-tool"` (skipped silently) when the payload's `name` is not
 * a `trst_`-prefixed tool name, `undefined` (skipped with a warning) when the
 * payload is malformed, and the mapped tool definition otherwise.
 */
function parsePerWorkflowToolJson(item: unknown): ParsedPerWorkflowTool | undefined {
  if (!isRecord(item)) {
    console.error("Warning: skipping malformed per-workflow MCP tool JSON: not an object.");
    return undefined;
  }

  const name = item.name;
  if (typeof name !== "string" || !name.startsWith("trst_")) {
    return "not-a-tool";
  }

  if (!validateStructural(item)) {
    console.error(
      `Warning: skipping malformed per-workflow MCP tool JSON "${name}": missing required fields (schemaVersion, name, workflowRef, description, generatedBy).`,
    );
    return undefined;
  }

  const workflowRef = item.workflowRef as string;
  if (workflowRef.trim() === "") {
    console.error(
      `Warning: skipping malformed per-workflow MCP tool JSON "${name}": workflowRef must be a non-empty string.`,
    );
    return undefined;
  }

  const inputSchema = parseToolInputSchema(item.inputSchema);
  if (inputSchema === undefined) {
    console.error(
      `Warning: skipping malformed per-workflow MCP tool JSON "${name}": inputSchema must be an object with optional properties/required.`,
    );
    return undefined;
  }

  return {
    name,
    description: item.description as string,
    workflowRef,
    inputSchema,
  };
}

function parseToolInputSchema(
  value: unknown,
): PerWorkflowToolDefinition["inputSchema"] | undefined {
  if (value === undefined) {
    return { type: "object", properties: {} };
  }
  if (!isRecord(value)) {
    return undefined;
  }

  const properties = value.properties ?? {};
  if (!isRecord(properties)) {
    return undefined;
  }

  const required = value.required;
  if (required !== undefined && (!Array.isArray(required) || !required.every(isString))) {
    return undefined;
  }

  return {
    type: "object",
    properties,
    ...(required === undefined ? {} : { required: required as readonly string[] }),
  };
}

function readRawJsonRecord(filePath: string, label: string): Record<string, unknown> | undefined {
  if (!existsSync(filePath)) {
    return undefined;
  }
  let content: string;
  try {
    content = readFileSync(filePath, "utf8");
  } catch {
    console.error(`Warning: unable to read ${label}: skip`);
    return undefined;
  }
  try {
    const parsed = JSON.parse(content) as unknown;
    return isRecord(parsed) ? parsed : undefined;
  } catch (error) {
    console.error(
      `Warning: skipping malformed config file ${label}: ${error instanceof Error ? error.message : error}`,
    );
    return undefined;
  }
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
